import{_ as a,o as i,c as t,ag as o}from"./chunks/framework.D9kpkP22.js";const m=JSON.parse('{"title":"Gameplay Mechanics","description":"","frontmatter":{},"headers":[],"relativePath":"icedspear/mechanics.md","filePath":"icedspear/mechanics.md"}'),l={name:"icedspear/mechanics.md"};function n(s,e,r,c,d,h){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="gameplay-mechanics" tabindex="-1">Gameplay Mechanics <a class="header-anchor" href="#gameplay-mechanics" aria-label="Permalink to &quot;Gameplay Mechanics&quot;">​</a></h1><p>IcedSpear introduces several gameplay mechanics that automate map management and enhance the player experience.</p><h2 id="map-lifecycle" tabindex="-1">Map Lifecycle <a class="header-anchor" href="#map-lifecycle" aria-label="Permalink to &quot;Map Lifecycle&quot;">​</a></h2><p>IcedSpear manages maps through a state-based lifecycle to ensure smooth gameplay and resource efficiency.</p><ol><li><strong>Creation</strong>: When a player requests a map (or a party leader warps their party), IcedSpear creates a new temporary world.</li><li><strong>Preparation</strong>: <ul><li>The map&#39;s schematic is pasted into the world.</li><li>The plugin scans for a <strong>Gold Block</strong> to determine the spawn point.</li></ul></li><li><strong>Waiting</strong>: Players are teleported to the map and held in a waiting state until the map is fully ready.</li><li><strong>Running</strong>: Once players are in position, the game begins. The timer starts when they move.</li><li><strong>Cleanup</strong>: When all players leave, the world is unloaded and deleted to free up server resources.</li></ol><h2 id="special-blocks" tabindex="-1">Special Blocks <a class="header-anchor" href="#special-blocks" aria-label="Permalink to &quot;Special Blocks&quot;">​</a></h2><p>Schematic designers can use specific blocks to define gameplay elements. These blocks are detected automatically when the map is loaded or during gameplay.</p><h3 id="gold-block-spawn-point" tabindex="-1">Gold Block (Spawn Point) <a class="header-anchor" href="#gold-block-spawn-point" aria-label="Permalink to &quot;Gold Block (Spawn Point)&quot;">​</a></h3><ul><li><strong>Function</strong>: Defines the starting spawn location for the map.</li><li><strong>Usage</strong>: Place a single Gold Block in your schematic where you want players to spawn.</li><li><strong>Behavior</strong>: <ul><li>On map load, the plugin scans the schematic bounds for <code>Material.GOLD_BLOCK</code>.</li><li>The spawn point is set to the center of the top of this block.</li><li>If no Gold Block is found, the spawn defaults to <code>0, 100, 0</code> (plus an offset).</li></ul></li></ul><h3 id="diamond-block-finish-line" tabindex="-1">Diamond Block (Finish Line) <a class="header-anchor" href="#diamond-block-finish-line" aria-label="Permalink to &quot;Diamond Block (Finish Line)&quot;">​</a></h3><ul><li><strong>Function</strong>: Marks the end of the map.</li><li><strong>Usage</strong>: Place Diamond Blocks at the end of the course.</li><li><strong>Behavior</strong>: <ul><li>When a player steps on a Diamond Block (specifically, when the block directly <em>under</em> them is <code>Material.DIAMOND_BLOCK</code>), the run is considered finished.</li><li><strong>Timer Stop</strong>: The player&#39;s timer is stopped immediately, and their time is recorded.</li><li><strong>Flight Mode</strong>: The player is automatically given flight capabilities (<code>/fly</code>) to spectate others or explore.</li><li><strong>Completion Message</strong>: A &quot;FINISHED!&quot; message is displayed with the final time.</li></ul></li></ul><h2 id="timer-system" tabindex="-1">Timer System <a class="header-anchor" href="#timer-system" aria-label="Permalink to &quot;Timer System&quot;">​</a></h2><p>IcedSpear includes a built-in precision timer for competitive gameplay.</p><ul><li><strong>Start</strong>: The timer begins automatically when a player moves from their spawn position.</li><li><strong>Tracking</strong>: Time is tracked in milliseconds.</li><li><strong>Display</strong>: An action bar displays the current run time in real-time.</li><li><strong>Leaderboards</strong>: Upon finishing, the time is compared against the map&#39;s leaderboard (if enabled).</li></ul><h2 id="game-rules" tabindex="-1">Game Rules <a class="header-anchor" href="#game-rules" aria-label="Permalink to &quot;Game Rules&quot;">​</a></h2><p>By default, map instances are configured for parkour/adventure gameplay. These settings can be customized in the <code>world-gamerules</code> section of <a href="./configuration.html">config.yml</a>.</p><ul><li><strong>Daylight Cycle</strong>: Frozen (default: <code>doDaylightCycle: false</code>).</li><li><strong>Weather</strong>: Locked (default: <code>doWeatherCycle: false</code>).</li><li><strong>Mob Spawning</strong>: Disabled (default: <code>doMobSpawning: false</code>).</li><li><strong>Gamemode</strong>: Adventure/Survival (configurable via <code>default-gamemode</code>).</li></ul>',17)])])}const g=a(l,[["render",n]]);export{m as __pageData,g as default};
